def parse_range(header, size):
    if not header.startswith('bytes='):
        return None
    ranges_str = header[6:].strip()
    if not ranges_str:
        return None

    result = []
    for part in ranges_str.split(','):
        part = part.strip()
        if not part:
            continue

        if '-' not in part:
            return None

        # split only on the first dash
        dash_idx = part.find('-')
        start_str = part[:dash_idx]
        end_str = part[dash_idx+1:]

        # parse start
        if start_str:
            try:
                start = int(start_str)
            except ValueError:
                return None
            if start < 0 or start >= size:
                continue  # unsatisfiable, skip
        else:
            start = None

        # parse end
        if end_str:
            try:
                end = int(end_str)
            except ValueError:
                return None
            if end < 0:
                return None
        else:
            end = None

        # suffix range (start missing)
        if start is None:
            if end is None:
                return None
            suffix_len = end
            if suffix_len == 0:
                continue
            if suffix_len > size:
                start = 0
                end = size - 1
            else:
                start = size - suffix_len
                end = size - 1
        else:
            # start present
            if end is None:
                end = size - 1
            else:
                if end >= size:
                    end = size - 1
                elif end < start:
                    continue  # unsatisfiable

        # final sanity check
        if start > end or start >= size:
            continue

        result.append((start, end))

    if not result:
        return None
    return result
