def cmp_semver(a: str, b: str) -> int:
    def parse(v: str):
        # Strip build metadata
        core = v.split('+', 1)[0]
        # Split core into version and pre‑release
        if '-' in core:
            ver_part, pre_part = core.split('-', 1)
        else:
            ver_part, pre_part = core, ''
        # Parse version numbers
        parts = list(map(int, ver_part.split('.')))
        # Pad to at least three components
        while len(parts) < 3:
            parts.append(0)
        # Parse pre‑release identifiers
        pre_ids = []
        if pre_part:
            for pid in pre_part.split('.'):
                if pid.isdigit():
                    pre_ids.append(int(pid))
                else:
                    pre_ids.append(pid)
        return parts[:3], pre_ids

    ver_a, pre_a = parse(a)
    ver_b, pre_b = parse(b)

    # Compare major, minor, patch numerically
    for i in range(3):
        if ver_a[i] < ver_b[i]:
            return -1
        if ver_a[i] > ver_b[i]:
            return 1

    # Versions are equal so far; handle pre‑release
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1          # a has no pre‑release → higher
    if not pre_b:
        return -1         # b has no pre‑release → higher

    # Both have pre‑release identifiers
    for id_a, id_b in zip(pre_a, pre_b):
        if isinstance(id_a, int) and isinstance(id_b, int):
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
        elif isinstance(id_a, int) and isinstance(id_b, str):
            return -1       # numeric < alphanumeric
        elif isinstance(id_a, str) and isinstance(id_b, int):
            return 1        # alphanumeric > numeric
        else:               # both strings
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1

    # All compared identifiers equal; shorter list wins
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0
