import re

def gitignore_match(pattern: str, path: str) -> bool:
    # Normalize path: split into components, treat empty string as root
    if path == "":
        comps = []
    else:
        comps = path.split('/')

    # Determine if path is a directory (ends with '/')
    is_dir = path.endswith('/')

    # Strip trailing slash for pattern matching logic
    pat = pattern.rstrip('/')

    # Helper to convert a pattern segment to a regex fragment
    def seg_to_regex(seg: str) -> str:
        # Escape regex meta characters except *, ?, []
        seg = re.escape(seg)
        # Replace escaped * with .* (but not matching '/')
        seg = seg.replace(r'\*', '[^/]*')
        # Replace escaped ? with . (non-slash)
        seg = seg.replace(r'\?', '.')
        # Replace escaped [ with [ (character class)
        # No further action needed; [] are already regex character classes
        return seg

    # Split pattern into parts by '/'
    pat_parts = pat.split('/')

    # Case 1: pattern contains a leading slash -> anchored at root
    if pattern.startswith('/'):
        # Must match from the root, so number of parts must match
        if len(pat_parts) != len(comps):
            return False
        for i, part in enumerate(pat_parts):
            if part == '':
                continue
            if not seg_match(part, comps[i]):
                return False
        # If pattern ends with '/', it must match a directory
        if pattern.endswith('/'):
            return is_dir
        return True

    # Case 2: pattern contains '**/'
    if '**/' in pattern:
        # Split pattern into prefix and suffix around the first '**/'
        # We'll handle '**/' by allowing any number of directories before the suffix
        prefix, suffix = pattern.split('**/', 1)
        # If prefix is empty, we can start matching from the beginning
        if prefix == '':
            # suffix may start with '/' or not
            if suffix.startswith('/'):
                suffix = suffix[1:]
            suffix_parts = suffix.split('/')
            # suffix_parts may be empty
            if len(suffix_parts) == 0:
                # pattern is just '**/'
                return True
            # Check that the suffix matches the end of comps
            if len(comps) < len(suffix_parts):
                return False
            for i, part in enumerate(suffix_parts):
                if part == '':
                    continue
                if not seg_match(part, comps[-len(suffix_parts) + i]):
                    return False
            # If pattern ends with '/', it must match a directory
            if pattern.endswith('/'):
                return is_dir
            return True
        else:
            # prefix is non-empty, must match at the beginning
            prefix_parts = prefix.split('/')
            if len(comps) < len(prefix_parts):
                return False
            for i, part in enumerate(prefix_parts):
                if part == '':
                    continue
                if not seg_match(part, comps[i]):
                    return False
            # Now check suffix
            suffix_parts = suffix.split('/')
            if len(suffix_parts) == 0:
                # suffix is empty, so pattern matches exactly up to prefix
                if pattern.endswith('/'):
                    return is_dir
                return True
            # Check that suffix matches the end of comps
            if len(comps) < len(suffix_parts):
                return False
            for i, part in enumerate(suffix_parts):
                if part == '':
                    continue
                if not seg_match(part, comps[-len(suffix_parts) + i]):
                    return False
            # If pattern ends with '/', it must match a directory
            if pattern.endswith('/'):
                return is_dir
            return True

    # Case 3: pattern contains no slash (except possibly trailing)
    if '/' not in pat:
        # Simple pattern: matches any depth
        if pat == '':
            # Empty pattern matches everything
            return True
        # If pattern ends with '/', it must match a directory
        if pattern.endswith('/'):
            return is_dir
        # Otherwise, match any component
        for comp in comps:
            if seg_match(pat, comp):
                return True
        return False

    # Case 4: pattern contains a slash but not '**/'
    # Split pattern into parts
    pat_parts = pat.split('/')
    if len(pat_parts) != len(comps):
        return False
    for i, part in enumerate(pat_parts):
