            continue
        if not seg_match(part, comps[i]):
            return False
    # If pattern ends with '/', it must match a directory
    if pattern.endswith('/'):
        return is_dir
    return True

def seg_match(pattern_seg: str, path_seg: str) -> bool:
    # Convert pattern segment to regex
    regex = seg_to_regex(pattern_seg)
    # Match the entire segment
    return re.fullmatch(regex, path_seg) is not None
