class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.min_freq = 0
        self.key_node = {}
        self.freq_nodes = {}

    def _add_node(self, node):
        f = node.freq
        if f not in self.freq_nodes:
            self.freq_nodes[f] = {}
        self.freq_nodes[f][node.key] = node

    def _remove_node(self, node):
        f = node.freq
        d = self.freq_nodes[f]
        del d[node.key]
        if not d:
            del self.freq_nodes[f]
            if f == self.min_freq:
                self.min_freq += 1

    def _move_to_next_freq(self, node):
        self._remove_node(node)
        node.freq += 1
        self._add_node(node)

    def get(self, key: int) -> int:
        if self.capacity == 0:
            return -1
        if key not in self.key_node:
            return -1
        node = self.key_node[key]
        self._move_to_next_freq(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_node:
            node = self.key_node[key]
            node.value = value
            self._move_to_next_freq(node)
        else:
            if len(self.key_node) >= self.capacity:
                # evict least frequently used, break ties by LRU
                f = self.min_freq
                d = self.freq_nodes[f]
                lru_key = next(iter(d))
                del d[lru_key]
                if not d:
                    del self.freq_nodes[f]
                del self.key_node[lru_key]
            new_node = Node(key, value, freq=1)
            self.key_node[key] = new_node
            self._add_node(new_node)
            self.min_freq = 1


class Node:
    __slots__ = ('key', 'value', 'freq', 'prev', 'next')
    def __init__(self, key, value, freq):
        self.key = key
        self.value = value
        self.freq = freq
        self.prev = None
        self.next = None
