def subtract(base, cuts):
    # Helper to merge overlapping or adjacent half‑open intervals
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals.sort(key=lambda x: x[0])
        merged = [list(intervals[0])]
        for s, e in intervals[1:]:
            if s <= merged[-1][1]:          # overlap or touch
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])
        return [tuple(m) for m in merged]

    # Merge cuts and base separately
    cuts = merge_intervals(cuts)
    base = merge_intervals(base)

    result = []
    i = j = 0
    while i < len(base):
        b_start, b_end = base[i]
        # skip cuts that end before the current base interval starts
        while j < len(cuts) and cuts[j][1] <= b_start:
            j += 1

        cur = b_start
        # process all cuts that intersect the current base interval
        while j < len(cuts) and cuts[j][0] < b_end:
            c_start, c_end = cuts[j]
            if c_start > cur:
                result.append((cur, c_start))
            cur = max(cur, c_end)
            if cur >= b_end:
                break
            j += 1

        if cur < b_end:
            result.append((cur, b_end))
        i += 1

    # Merge any adjacent intervals that may have been produced
    return merge_intervals(result)
