class WildcardTrie:
    def __init__(self):
        self.root = {}
        self.word_count = 0

    def add(self, word):
        node = self.root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        if '*' not in node:
            node['*'] = 0
            self.word_count += 1
            return True
        return False

    def remove(self, word):
        node = self.root
        path = []
        for ch in word:
            if ch not in node:
                return False
            path.append((node, ch))
            node = node[ch]
        if '*' not in node:
            return False
        node['*'] -= 1
        if node['*'] == 0:
            del node['*']
            self.word_count -= 1
            for parent, ch in reversed(path):
                if not parent[ch]:
                    del parent[ch]
                else:
                    break
        return True

    def _dfs(self, node, prefix, results):
        if '*' in node:
            results.append(prefix)
        for ch, child in node.items():
            if ch == '*':
                continue
            self._dfs(child, prefix + ch, results)

    def search(self, pattern):
        results = []
        self._search_helper(self.root, "", pattern, results)
        return sorted(results)

    def _search_helper(self, node, prefix, pattern, results):
        if not pattern:
            if '*' in node:
                results.append(prefix)
            return
        ch = pattern[0]
        if ch == '.':
            for child_ch, child_node in node.items():
                if child_ch == '*':
                    continue
                self._search_helper(child_node, prefix + child_ch, pattern[1:], results)
        else:
            if ch in node:
                self._search_helper(node[ch], prefix + ch, pattern[1:], results)
