import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return 0, [src]

    INF = float('inf')
    dist = {node: INF for node in graph}
    pred = {}
    dist[src] = 0
    heap = [(0, 0, src)]  # (total_cost, edge_count, node)

    while heap:
        cost, edges, u = heapq.heappop(heap)
        if cost > dist[u]:
            continue
        if u == dst:
            break
        for v, w in graph.get(u, []):
            new_cost = cost + w
            new_edges = edges + 1
            if new_cost < dist.get(v, INF):
                dist[v] = new_cost
                pred[v] = [u]
                heapq.heappush(heap, (new_cost, new_edges, v))
            elif new_cost == dist.get(v, INF):
                if v not in pred:
                    pred[v] = []
                if u not in pred[v]:
                    pred[v].append(u)

    if dst not in dist or dist[dst] == INF:
        return None, []

    # Reconstruct all best‑cost paths
    candidates = [[dst]]
    while candidates:
        path = candidates.pop()
        first = path[0]
        if first == src:
            break
        for prev in pred.get(first, []):
            candidates.append([prev] + path)

    # Choose lexicographically smallest among candidates
    best = min(candidates)
    return dist[dst], best
