import heapq
from collections import deque
from typing import Dict, List, Optional

def topo_lex(graph: Dict[int, List[int]]) -> Optional[List[int]]:
    # Build successor and predecessor maps
    succ: Dict[int, List[int]] = {}
    pred: Dict[int, List[int]] = {}
    all_nodes = set()

    for u, slist in graph.items():
        all_nodes.add(u)
        succ[u] = list(slist)          # copy to avoid mutating input
        for v in slist:
            all_nodes.add(v)
            pred.setdefault(v, []).append(u)

    # Ensure every node appears in both dictionaries
    for node in all_nodes:
        succ.setdefault(node, [])
        pred.setdefault(node, [])

    # Compute indegrees
    indegree = {node: len(pred[node]) for node in all_nodes}

    # Min‑heap of ready nodes (indegree == 0)
    ready = [node for node in all_nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order: List[int] = []
    while ready:
        u = heapq.heappop(ready)
        order.append(u)
        for v in succ[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(ready, v)

    if len(order) != len(all_nodes):
        return None          # cycle detected
    return order
