function debounce(fn, wait, options = {}) {
  const { leading = false, trailing = true } = options;
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let result = null;

  const cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  const flush = () => {
    cancel();
    if (timeoutId !== null) {
      result = fn.apply(lastThis, lastArgs);
      timeoutId = null;
    }
    return result;
  };

  const debounced = function (...args) {
    lastArgs = args;
    lastThis = this;

    const invoke = () => {
      result = fn.apply(this, args);
      timeoutId = null;
    };

    const shouldInvoke = () => {
      if (timeoutId !== null) {
        return false;
      }
      if (leading && timeoutId === null) {
        return true;
      }
      return false;
    };

    if (shouldInvoke()) {
      invoke();
    } else if (trailing) {
      cancel();
      timeoutId = setTimeout(invoke, wait);
    }

    return result;
  };

  debounced.cancel = cancel;
  debounced.flush = flush;

  return debounced;
}

module.exports = debounce;
