class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const listeners = this.events.get(event);
    listeners.push(fn);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const wrapped = (...args) => {
      this.off(event, wrapped);
      fn(...args);
    };
    return this.on(event, wrapped);
  }

  off(event, fn) {
    if (!this.events.has(event)) return;
    const listeners = this.events.get(event);
    const index = listeners.indexOf(fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return 0;
    const listeners = this.events.get(event);
    const toInvoke = [...listeners];
    let count = 0;
    const errors = [];

    for (const fn of toInvoke) {
      try {
        fn(...args);
        count++;
      } catch (err) {
        errors.push(err);
      }
    }

    if (errors.length > 0) {
      throw errors[0];
    }

    return count;
  }
}

module.exports = Emitter;
