function get(doc, pointer) {
  if (pointer === '') return doc;
  if (!pointer.startsWith('/')) throw new Error('Invalid JSON Pointer');

  let tokens = pointer.substring(1).split('/');
  for (let i = 0; i < tokens.length; i++) {
    tokens[i] = tokens[i].replace(/~1/g, '/').replace(/~0/g, '~');
    if (doc === null || doc === undefined) return undefined;
    if (Array.isArray(doc)) {
      const index = parseInt(tokens[i], 10);
      if (isNaN(index) || index < 0 || index >= doc.length) return undefined;
      doc = doc[index];
    } else if (typeof doc === 'object') {
      if (!(tokens[i] in doc)) return undefined;
      doc = doc[tokens[i]];
    } else {
      return undefined;
    }
  }
  return doc;
}

function set(doc, pointer, value) {
  if (pointer === '') return (doc = value);
  if (!pointer.startsWith('/')) throw new Error('Invalid JSON Pointer');

  let tokens = pointer.substring(1).split('/');
  for (let i = 0; i < tokens.length - 1; i++) {
    tokens[i] = tokens[i].replace(/~1/g, '/').replace(/~0/g, '~');
    if (doc === null || doc === undefined) {
      const next = tokens[i + 1];
      const isIndex = /^\d+$/.test(next);
      const isArray = isIndex || next === '-';
      doc = isArray ? [] : {};
    }
    if (Array.isArray(doc)) {
      const index = parseInt(tokens[i], 10);
      if (isNaN(index) || index < 0) {
        doc.push(doc = {});
      } else if (index >= doc.length) {
        while (doc.length < index) doc.push(undefined);
        doc.push(doc = {});
      } else {
        doc = doc[index];
      }
    } else if (typeof doc === 'object') {
      if (!(tokens[i] in doc)) doc[tokens[i]] = {};
      doc = doc[tokens[i]];
    } else {
      doc = {};
    }
  }

  const lastToken = tokens[tokens.length - 1].replace(/~1/g, '/').replace(/~0/g, '~');
  if (Array.isArray(doc)) {
    const index = parseInt(lastToken, 10);
    if (isNaN(index) || index < 0) {
      doc.push(value);
    } else if (index >= doc.length) {
      while (doc.length < index) doc.push(undefined);
      doc[index] = value;
    } else {
      doc[index] = value;
    }
  } else if (typeof doc === 'object') {
    doc[lastToken] = value;
  } else {
    doc = value;
  }

  return doc;
}

