class Spreadsheet:
    def __init__(self):
        self.values = {}                     # cell -> numeric value
        self.formulas = {}                   # cell -> formula string
        self.dependencies = {}               # cell -> set of cells it depends on
        self.dependents = {}                 # cell -> set of cells that depend on it
        self.dirty = set()                   # cells whose value needs recomputation

    def _parse_formula(self, formula):
        """Return a tuple (operation, operands) for a formula string."""
        s = formula[1:]                     # strip leading '='
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isalpha():                # cell reference
                j = i
                while j < n and (s[j].isalpha() or s[j].isdigit()):
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif ch.isdigit():              # integer literal
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(int(s[i:j]))
                i = j
            elif ch in '+-*':
                tokens.append(ch)
                i += 1
            else:
                i += 1                      # ignore unexpected characters
        # evaluate left‑to‑right (no precedence)
        result = tokens[0]
        idx = 1
        while idx < len(tokens):
            op = tokens[idx]
            idx += 1
            right = tokens[idx]
            idx += 1
            if op == '+':
                result += right
            elif op == '-':
                result -= right
            elif op == '*':
                result *= right
        return result

    def _get_value(self, cell):
        """Return the numeric value of a cell (0 if unset)."""
        if cell in self.values:
            return self.values[cell]
        if cell in self.formulas:
            return self._parse_formula(self.formulas[cell])
        return 0

    def set(self, cell, value):
        """Set a cell to a number or a formula string. Raises ValueError on cycle."""
        # If the value is unchanged, nothing to do.
        if cell in self.values and self.values[cell] == value:
            return
        if cell in self.formulas and self.formulas[cell] == value:
            return

        # Detect cycles using the current dependency graph.
        visited = set()
        stack = set()

        def dfs(c):
            if c in stack:
                return True
            if c in visited:
                return False
            visited.add(c)
            stack.add(c)
            for dep in self.dependencies.get(c, set()):
                if dfs(dep):
                    return True
            stack.remove(c)
            return False

        if isinstance(value, str) and value.startswith('='):
            # Parse the formula to collect its dependencies.
            s = value[1:]
            deps = set()
            i = 0
            n = len(s)
            while i < n:
                ch = s[i]
                if ch.isalpha():
                    j = i
                    while j < n and (s[j].isalpha() or s[j].isdigit()):
                        j += 1
                    deps.add(s[i:j])
                    i = j
                elif ch.isdigit():
                    j = i
                    while j < n and s[j].isdigit():
                        j += 1
                    i = j
                elif ch in '+-*':
                    i += 1
                else:
                    i += 1
            # Temporarily replace the cell's dependencies.
            old_deps = self.dependencies.get(cell, set())
            self.dependencies[cell] = deps
            if dfs(cell):
                # Cycle detected – revert and raise.
                self.dependencies[cell] = old_deps
                raise ValueError("Reference cycle detected")
        else:
            # Numeric value – no dependencies.
            self.dependencies[cell] = set()

        # Record the new value/formula.
        if isinstance(value, str) and value.startswith('='):
            self.formulas[cell] = value
            del self.values[cell]
        else:
            self.values[cell] = value
            if cell in self.formulas:
                del self.formulas[cell]

        # Propagate changes to dependents.
        self.dirty.add(cell)
        stack = [cell]
        while stack:
            cur = stack.pop()
            for dep in self.dependents.get(cur, set()):
                self.dirty.add(dep)
                stack.append(dep)

    def get(self, cell):
        """Return the current numeric value of a cell (O(1) amortised)."""
        if cell in self.dirty:
            # Recompute the cell's value.
            if cell in self.values:
                new_val = self.values[cell]
            elif cell in self.formulas:
                new_val = self._parse_formula(self.formulas[cell])
            else:
                new_val = 0
            self.values[cell] = new_val
            del self.formulas[cell]
            self.dirty.remove(cell)
            # Update dependents' dirty status.
            for dep in self.dependents.get(cell, set()):
                self.dirty.add(dep)
        return self.values.get(cell, 0)
