function sqlTag(strings, ...values) {
  let text = '';
  const valuesArray = [];
  let placeholderIndex = 1;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      const value = values[i];
      if (value && typeof value === 'object' && value.sqlTag) {
        // INLINE a nested sqlTag result
        const nested = value;
        const nestedText = nested.text;
        const nestedValues = nested.values;
        // Replace placeholders in nested text with renumbered ones
        const renumberedText = nestedText.replace(/\$(\d+)/g, (_, num) => {
          const newNum = Number(num) + (placeholderIndex - 1);
          return `$${newNum}`;
        });
        text += renumberedText;
        // Merge nested values
        valuesArray.push(...nestedValues);
        // Update placeholder index
        placeholderIndex += nestedValues.length;
      } else if (Array.isArray(value)) {
        // Handle array: convert to parenthesized comma-separated placeholders
        const placeholders = value.map(() => `$${placeholderIndex++}`).join(', ');
        text += `(${placeholders})`;
        // No values added for array elements
      } else {
        // Simple value: add as a placeholder
        text += `$${placeholderIndex}`;
        valuesArray.push(value);
        placeholderIndex++;
      }
    }
  }

  return { text, values: valuesArray };
}

module.exports = sqlTag;
