function zipLongest(fill, ...iterables) {
  if (iterables.length === 0) {
    return (function* () {})();
  }

  const iterators = iterables.map(it => it[Symbol.iterator]());
  const active = iterators.map(it => !it.next().done);

  return (function* () {
    while (active.some(Boolean)) {
      const row = [];
      for (let i = 0; i < iterators.length; i++) {
        if (active[i]) {
          const { value, done } = iterators[i].next();
          if (done) {
            active[i] = false;
            row.push(fill);
          } else {
            row.push(value);
          }
        } else {
          row.push(fill);
        }
      }
      yield row;
    }
  })();
}

module.exports = zipLongest;
