export class Bus<E extends Record<string, unknown>> {
  private listeners: Map<keyof E, Set<(payload: E[keyof E]) => void>> = new Map();

  on<K extends keyof E>(
    key: K,
    fn: (payload: E[K]) => void
  ): () => void {
    if (!this.listeners.has(key)) {
      this.listeners.set(key, new Set());
    }
    const set = this.listeners.get(key)!;
    set.add(fn);
    return () => {
      set.delete(fn);
      if (set.size === 0) {
        this.listeners.delete(key);
      }
    };
  }

  emit<K extends keyof E>(
    key: K,
    payload?: E[K]
  ): void {
    const type = typeof payload;
    const eventType = this.listeners.get(key);
    if (!eventType) return;

    if (type === 'undefined') {
      for (const fn of eventType) {
        fn(undefined as E[K]);
      }
    } else {
      for (const fn of eventType) {
        fn(payload);
      }
    }
  }
}
