    if (this.built) {
      throw new Error("Cannot set after build");
    }
    this.state[key] = value;
    return this;
  }

  build(): T {
    if (this.built) {
      throw new Error("Already built");
    }
    this.built = true;

    const requiredKeys = [] as RequiredKeys<T>[];
    const optionalKeys = [] as OptionalKeys<T>[];

    for (const key in this.state) {
      if (key in ({} as T)) {
        if (undefined === ({} as T)[key]) {
          requiredKeys.push(key as RequiredKeys<T>);
        } else {
          optionalKeys.push(key as OptionalKeys<T>);
        }
      }
    }

    for (const key of requiredKeys) {
      if (!(key in this.state)) {
        throw new Error(`Missing required key: ${key}`);
      }
    }

    return this.state as T;
  }
}

export function builder<T extends Record<string, any>>(): Builder<T> {
  return new Builder<T>();
}
