/**
 * A branded type utility that creates a nominal type.
 * T is the base type, B is the brand.
 */
export type Brand<T, B> = T & { __brand: B };

/**
 * The Email type is a branded string.
 */
export type Email = Brand<string, 'Email'>;

/**
 * Regular expression for validating email addresses.
 * This is a simplified version; for production use a more robust library.
 */
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Type guard to check if a string is a valid Email.
 * @param s The string to check.
 * @returns True if the string is a valid Email, false otherwise.
 */
export function isEmail(s: string): s is Email {
  return EMAIL_REGEX.test(s);
}

/**
 * Casts a string to an Email type.
 * Throws an error if the string is not a valid email address.
 * @param s The string to cast.
 * @returns The string cast as an Email.
 * @throws {Error} If the string is not a valid email address.
 */
export function asEmail(s: string): Email {
  if (!isEmail(s)) {
    throw new Error(`Invalid email address: ${s}`);
  }
  return s as Email;
}
