export type RouteParams<T extends string> = T extends `${string}:${infer P}/${infer Rest}`
  ? { [K in P]: string } & RouteParams<Rest>
  : T extends `${string}:${infer P}`
  ? { [K in P]: string }
  : {};

export type RouteHandler<T extends string> = T extends `${string}:${string}/${string}`
  ? (params: RouteParams<T>) => string
  : T extends `${string}:${string}`
  ? (params: RouteParams<T>) => string
  : () => string;

export type RouteMap<T extends Record<string, string>> = {
  [K in keyof T]: RouteHandler<T[K]>;
};

export function defineRoutes<T extends Record<string, string>>(routes: T): RouteMap<T> {
  const result = {} as RouteMap<T>;

  for (const [name, path] of Object.entries(routes)) {
    result[name] = ((params: any) => {
      if (path.includes(':')) {
        const paramNames = path.match(/:(\w+)/g)?.map(p => p.slice(1)) || [];
        for (const param of paramNames) {
          if (!(param in params)) {
            throw new Error(`Missing param: ${param}`);
          }
        }
        let interpolated = path;
        for (const [key, value] of Object.entries(params)) {
          interpolated = interpolated.replace(new RegExp(`:${key}`, 'g'), String(value));
        }
        return interpolated;
      } else {
        if (params && Object.keys(params).length > 0) {
          throw new Error('Unexpected params for path without parameters');
        }
        return path;
      }
    }) as RouteHandler<T[keyof T]>;
  }

  return result;
}
